        "bullets": [
          "Open a regional dossier and choose First Sighting.",
          "Read the target name and identify its strongest physical or behavioural clue.",
          "Clear Crossing Currents and Final Verdict, checking the target again in each room.",
          "Repeat for the other two dossiers until all nine tasks are marked complete.",
          "Return to the regional board and open The Return Current.",
          "Clear its phases and use Resolve the breach."
        ]
