      {
        "title": "Which systems a task measures",
        "text": [
          "Rescue-rate missions use a stable production figure without temporary Surge, Apex or event multipliers. That prevents a brief burst alone from satisfying every operation-growth assignment. Click-power missions use the click-power calculation, while resource missions distinguish total saved from the current bank.",
          "Research-earned tasks count research gained, not simply unspent research sitting in the wallet. Operation-specific tasks follow their named operation. Remaining-purchase tasks are capped by the number of upgrades still available, so the board does not ask you to buy an already exhausted permanent collection."
        ]
      },
      {
        "title": "Mission rewards feed the network",
        "text": [
          "Field Briefings and Crown Instinct can improve mission rewards, and events can temporarily change particular payout types. Completed missions add 0.2 breakthrough point and increase the run’s mission production factor by 1% per completion. That is an ongoing reason to keep the board moving.",
          "When you are unsure what to buy next, choose a useful purchase that also advances an assignment. Do not assume a mission asking for a bank target rewards spending immediately; read whether the metric is banked sharks, total rescues or a purchase count before changing your build."
        ]
      }
