          "The Rare targets here are Longnose Skate and White Skate. If only those remain, Barnacle's three-scroll quantity does not guarantee relevant progress. Celestial guarantees the Rare pool, while Seafoam offers seven slots with a two-Rare cap.",
          "Neither bottle is restricted to Coldwater Charts. A Rare can come from another set or repeat an owned slot. Keep the exact target titles alongside the 10/10 requirement when planning a duplicate exchange."
